import sys

def main():
    data = sys.stdin.read().split()
    g, a = data[0], data[1]
    n = len(g)
    res = ['X'] * n
    cnt = {}
    for i in range(n):
        if g[i] == a[i]:
            res[i] = 'G'
        else:
            cnt[a[i]] = cnt.get(a[i], 0) + 1
    for i in range(n):
        if res[i] == 'G':
            continue
        if cnt.get(g[i], 0) > 0:
            res[i] = 'Y'
            cnt[g[i]] -= 1
    print(''.join(res))

